mapper.select:
		/*
             SQL ID : OnlnPltfrmAuthrtDAO.onlnPltfrmAuthrtIdSelect
             설  명  : 온라인플랫폼권한아이디조회
         */
        SELECT
			ONLN_PLTFRM_AUTHRT_ID
		  FROM TB_LMS_ONLN_PLTFRM_AUTHRT
		 WHERE ONLN_PLTFRM_STNG_ID = #{onlnPltfrmStngId}
		   AND AUTHRT_EML = #{authrtEml}

mapper.delete:
		/*
             SQL ID : OnlnPltfrmAuthrtDAO.onlnPltfrmAuthrtBulkDelete
             설  명 : 온라인플랫폼권한일괄삭제
         */
        DELETE FROM TB_LMS_ONLN_PLTFRM_AUTHRT
		 WHERE ONLN_PLTFRM_STNG_ID = #{onlnPltfrmStngId}
